import{_ as e,o as a,c as o,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Crimson/SeaStor OSD 2020-06-24","description":"","frontmatter":{"title":"Ceph Crimson/SeaStor OSD 2020-06-24","date":"2020-06-24T00:00:00.000Z","updated":"2020-06-25T00:00:00.000Z","tags":["Ceph","Distributed Storage","CephFS","Performance Optimization","Automated Testing"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Crimson_SeaStor_OSD_2020-06-24.md","filePath":"posts/2020/Ceph_Crimson_SeaStor_OSD_2020-06-24.md","lastUpdated":1780459816000}'),r={name:"posts/2020/Ceph_Crimson_SeaStor_OSD_2020-06-24.md"};function i(n,t,s,h,m,p){return a(),o("div",null,[...t[0]||(t[0]=[l('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="参会人员" tabindex="-1">参会人员 <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员&quot;">​</a></h4><ul><li>Tommy</li><li>其他相关人员</li></ul><h4 id="会议时间" tabindex="-1">会议时间 <a class="header-anchor" href="#会议时间" aria-label="Permalink to &quot;会议时间&quot;">​</a></h4><ul><li>日期：2020-06-24</li><li>时间：具体时间未提供</li></ul><h4 id="会议议题" tabindex="-1">会议议题 <a class="header-anchor" href="#会议议题" aria-label="Permalink to &quot;会议议题&quot;">​</a></h4><ol><li><strong>Ceph存储系统开发进展</strong></li><li><strong>技术问题讨论与解决方案</strong></li><li><strong>后续行动计划</strong></li></ol><h4 id="会议内容" tabindex="-1">会议内容 <a class="header-anchor" href="#会议内容" aria-label="Permalink to &quot;会议内容&quot;">​</a></h4><ol><li><p><strong>Ceph存储系统开发进展</strong></p><ul><li>Tommy上周专注于处理异步another tree，并审查了Ritek编写的blue storylines。</li><li>本周计划完成heartbeat的审查，并处理工程师Stem提交的replicas by place。</li></ul></li><li><p><strong>技术问题讨论</strong></p><ul><li><strong>缓存依赖追踪</strong>：Tommy正在为缓存添加支持，以跟踪依赖关系并确保所有父级extent被固定，确保逻辑extent（如extent tree或oh no tree extent）在内存中时，其所有映射页也在内存中。</li><li><strong>零拷贝数据序列化</strong>：Tommy正在调查零拷贝数据序列化方法，如flat buffers，以解决当前编码和解码方法消耗过多CPU的问题。</li><li><strong>Crimson测试与优化</strong>：Tommy强调在Crimson运行自动化测试之前，不考虑进行性能优化，以避免引入新的bug。</li></ul></li><li><p><strong>后续行动计划</strong></p><ul><li><strong>Crimson自动化测试</strong>：Tommy计划确保Crimson的自动化测试工作，以便后续可以自信地进行性能优化。</li><li><strong>Topology工作</strong>：Tommy提到关于topology的工作接近完成，并寻求志愿者来处理pathology代码。</li><li><strong>技术支持与访问</strong>：讨论了获取实验室访问权限的流程，以便能够运行pathology作业。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>确保Crimson的自动化测试工作是当前的首要任务。</li><li>需要获取实验室访问权限以进行进一步的开发和测试。</li></ul><h4 id="后续行动" tabindex="-1">后续行动 <a class="header-anchor" href="#后续行动" aria-label="Permalink to &quot;后续行动&quot;">​</a></h4><ul><li>Tommy将发送相关链接并在30分钟后再次联系。</li><li>评估使用现有dot pi安装Crimson OSD的工作量，并选择更简便的方法。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><ul><li>会议在感谢和告别中结束。</li></ul><p><strong>备注</strong>：会议中提到的技术术语和项目名称如“async another tree”、“heartbeat”、“replicas by place”、“flat buffers”等，保留了英文原文以确保准确性。</p>',16)])])}const _=e(r,[["render",i]]);export{d as __pageData,_ as default};
